from __future__ import annotations

from copy import deepcopy
import hashlib

CONFERRING_BASIS_TYPES = {"grant", "policy", "delegation"}

def _basis_for(domain, operation, *, subject="actor", scope="global", target_class="record", target=None,
               basis_type="grant", conf=True, current=True, valid=True, authority_domain=None, extra=None):
    basis = {
        "basis_type": basis_type,
        "authority_conferring": conf,
        "subject": subject,
        "domain": domain,
        "operation": operation,
        "scope": scope,
        "target_class": target_class,
        "current": current,
        "valid": valid,
    }
    if target is not None:
        basis["target"] = target
    if authority_domain is not None:
        basis["authority_domain"] = authority_domain
    if extra:
        basis.update(extra)
    return basis

def _base_case(case_id, request_kind):
    source_hash = "sha256:" + hashlib.sha256(case_id.encode("utf-8")).hexdigest()
    proposals = [
        {"id": "p1", "dimension": "role_binding",
         "payload": {"predicate": "inspect", "subject": "Dana", "object": "vessel"}},
        {"id": "p2", "dimension": "quantifier", "embedding": "quantifier",
         "payload": {"quantifier": "every", "population": "tech"}},
    ]
    o1 = {"id": "o1", "authority_kind": "observation", "producer_type": "source_observer",
          "source_hash": source_hash, "dependencies": [], "status": "established"}
    o2 = {"id": "o2", "authority_kind": "observation", "producer_type": "source_observer",
          "source_hash": source_hash, "dependencies": [], "status": "established"}
    m1 = {"id": "m1", "authority_kind": "measurement", "producer_type": "language_instrument",
          "source_hash": source_hash, "dependencies": ["o1"], "status": "established",
          "subject": "actor", "domain": "measurement", "operation": "measure", "scope": "global",
          "target_class": "record", "basis": _basis_for("measurement", "measure")}
    m2 = deepcopy(m1)
    m2["id"] = "m2"
    m2["dependencies"] = ["o2"]
    s1 = {"id": "s1", "authority_kind": "semantic", "producer_type": "semantic_validator",
          "source_hash": source_hash, "dependencies": ["m1"], "status": "established",
          "subject": "actor", "domain": "semantic", "operation": "interpret", "scope": "global",
          "target_class": "record", "proposal_id": "p1", "claim_level": "typed_semantic",
          "preserves_embedding": True,
          "basis": _basis_for("semantic", "interpret",
                              extra={"semantic_dimensions": ["role_binding"], "allowed_embeddings": []})}
    s2 = {"id": "s2", "authority_kind": "semantic", "producer_type": "semantic_validator",
          "source_hash": source_hash, "dependencies": ["m2"], "status": "established",
          "subject": "actor", "domain": "semantic", "operation": "interpret", "scope": "global",
          "target_class": "record", "proposal_id": "p2", "claim_level": "embedded_semantic",
          "preserves_embedding": True,
          "basis": _basis_for("semantic", "interpret",
                              extra={"semantic_dimensions": ["quantifier"], "allowed_embeddings": ["quantifier"]})}
    c1 = {"id": "c1", "authority_kind": "composition", "producer_type": "composition_governor",
          "source_hash": source_hash, "dependencies": ["s1", "s2"], "status": "established",
          "subject": "actor", "domain": "composition", "operation": "compose", "scope": "global",
          "target_class": "record", "component_dimensions": ["role_binding", "quantifier"],
          "basis": _basis_for("composition", "compose",
                              extra={"component_dimensions": ["role_binding", "quantifier"],
                                     "composition_rule": "conjoin"})}
    d1 = {"id": "d1", "authority_kind": "decision", "producer_type": "decision_engine",
          "source_hash": source_hash, "dependencies": ["c1"], "status": "established",
          "subject": "actor", "domain": "decision", "operation": "decide", "scope": "global",
          "target_class": "record", "basis": _basis_for("decision", "decide")}
    receipts = [o1, o2, m1, m2, s1, s2, c1, d1]
    requests = {
        "observation": deepcopy(o1),
        "measurement": deepcopy(m1),
        "semantic": deepcopy(s1),
        "comparison": {"id": "req", "authority_kind": "comparison", "producer_type": "comparison_engine",
                       "source_hash": source_hash, "dependencies": ["m1", "m2"], "status": "established",
                       "relation": "EXACT_AGREEMENT"},
        "resolution": {"id": "req", "authority_kind": "resolution", "producer_type": "authority_resolver",
                       "source_hash": source_hash, "dependencies": ["s1"], "status": "established",
                       "subject": "actor", "domain": "resolution", "operation": "resolve", "scope": "global",
                       "target_class": "record", "resolves_ids": ["r1"],
                       "basis": _basis_for("resolution", "resolve")},
        "composition": deepcopy(c1),
        "decision": deepcopy(d1),
        "action": {"id": "req", "authority_kind": "action", "producer_type": "action_authorizer",
                   "source_hash": source_hash, "dependencies": ["d1"], "status": "established",
                   "subject": "actor", "domain": "action", "operation": "execute", "scope": "global",
                   "target_class": "record",
                   "basis": _basis_for("action", "execute", authority_domain="action")},
        "verification": {"id": "req", "authority_kind": "verification", "producer_type": "outcome_verifier",
                         "source_hash": source_hash, "dependencies": ["o1"], "status": "established",
                         "subject": "actor", "domain": "verification", "operation": "verify", "scope": "global",
                         "target_class": "record",
                         "basis": _basis_for("verification", "verify", authority_domain="verification")},
    }
    return {
        "id": case_id,
        "family": request_kind,
        "tags": [],
        "raw_source": {"text": f"source for {case_id}", "bytes_id": case_id},
        "source_hash": source_hash,
        "proposals": proposals,
        "receipts": receipts,
        "conflicts": [],
        "residues": [],
        "comparison_receipts": [],
        "request": requests[request_kind],
    }

def _resolve_path(obj, path):
    cur = obj
    for key in path[:-1]:
        cur = cur[key]
    return cur, path[-1] if path else None

def _apply_ops(case, ops):
    for op, path, value in ops:
        path = tuple(path)
        if op == "set":
            if not path:
                raise ValueError("root set not supported")
            parent, key = _resolve_path(case, path)
            parent[key] = deepcopy(value)
        elif op == "del":
            parent, key = _resolve_path(case, path)
            del parent[key]
        elif op == "append":
            cur = case
            for key in path:
                cur = cur[key]
            cur.append(deepcopy(value))
        else:
            raise ValueError(f"unknown case mutation op: {op}")
    return case

