def load_cases():
    cases = []
    for spec in _SPECS:
        case = _base_case(spec["id"], spec["kind"])
        _apply_ops(case, spec["ops"])
        case["tags"] = deepcopy(spec["tags"])
        if spec.get("pair") is not None:
            case["pair"] = deepcopy(spec["pair"])
        # Normalize any appended receipt placeholder to the case source identity.
        for receipt in case.get("receipts", []):
            if receipt.get("source_hash") == "PLACEHOLDER":
                receipt["source_hash"] = case["source_hash"]
        case["expected"] = deepcopy(_EXPECTED[case["id"]])
        cases.append(case)
    if len(cases) != 94:
        raise RuntimeError(f"sealed case count mismatch: {len(cases)}")
    ids = [c["id"] for c in cases]
    if len(set(ids)) != len(ids):
        raise RuntimeError("duplicate sealed case id")
    return cases

CASES = load_cases()
